// Pull the question from webhook ?q= or use a manual default.
const item = $input.first() ? $input.first().json : {};
const q = (item.query && item.query.q) || item.q || item.question || 'What does the runbook say about restoring n8n from backup?';
return [{ json: { question: String(q).trim(), top_k: 5 } }];

// Ollama /api/embeddings returns { embedding: [...] }.
const emb = $input.first().json.embedding;
if (!Array.isArray(emb)) {
  throw new Error('No embedding returned from Ollama: ' + JSON.stringify($input.first().json).slice(0,200));
}
const vectorLiteral = '[' + emb.join(',') + ']';
const question = $('Read Question').first().json.question;
const top_k = $('Read Question').first().json.top_k || 5;
return [{ json: { question: question, top_k: top_k, vectorLiteral: vectorLiteral, dim: emb.length } }];

const question = $('Format Vector').first().json.question;
const rows = $input.all().map(i => i.json).filter(r => r && r.text);
const parts = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  const src = (r.metadata && (r.metadata.source || r.metadata.title)) || ('doc#' + (i+1));
  parts.push('[' + (i+1) + '] (source: ' + src + ')
' + r.text);
}
const context = rows.length === 0 ? '(no matching documents found in the knowledge base)' : parts.join('

');
const system = "You are Ada, the ops/engineer for a solo agency's local automation stack (Docker n8n, Ollama on host, Postgres+pgvector, localhost-only, MacBook M3 Pro 38GB, RAM-tight). Be terse and technical — no preamble, no encouragement. Give the command, code (in fenced blocks), or diff first, then at most one line of why. State assumptions explicitly. Flag anything destructive, anything that exposes a port to the LAN, anything that loads two large models at once, or anything touching secrets. Prefer absolute paths. If unsure, say so in one line.";
const prompt = system + '

Answer the question using ONLY the retrieved context below. Cite the bracketed source numbers you used, e.g. [1]. If the context does not contain the answer, say so in one line and do not invent facts.

=== RETRIEVED CONTEXT ===
' + context + '

=== QUESTION ===
' + question + '

=== ANSWER ===';
return [{ json: { model: 'qwen3:8b', prompt: prompt, question: question, matches: rows.length } }];
